    def _run_actor_sched(self) -> None:
        # invoke generator in message queue
        sched = ActorScheduler()
        sched.new_actor("pyjab", self.win32utils.setup_msg_pump())
        sched.run()

    @staticmethod
    def find_window_by_title(title_pattern):
        """Find window by partial or exact title"""  
        def callback(hwnd, windows):
            if win32gui.IsWindowVisible(hwnd):
                window_title = win32gui.GetWindowText(hwnd)
                if title_pattern.lower() in window_title.lower():
                    windows.update({hwnd:window_title})
            return True

        windows = {}
        win32gui.EnumWindows(callback, windows)
        return windows

    def get_window_by_pid(self, pid):
        """  
        Retrieve the HWND and title of a window based on the PID.  
        Args:  
            pid (int): The PID of the process.  
        Returns:  
            tuple: A tuple containing the HWND and window title.  
        """
        windows = {}
        hwnds = []
        win32gui.EnumWindows(lambda hwnd, param: param.append(hwnd), hwnds)
        for hwnd in hwnds:
            _, found_pid = win32process.GetWindowThreadProcessId(hwnd)
            if found_pid == pid and win32gui.IsWindow(hwnd): #and self._is_java_window(hwnd):
                window_title = win32gui.GetWindowText(hwnd)  
                window_class = win32gui.GetClassName(hwnd)
                if ('java' in window_class.lower() or
                    'swing' in window_class.lower() or   
                    'awt' in window_class.lower() or
                    self.title in window_title
                    ):
                    windows.update({hwnd:[window_title, window_class]})
        return  windows
    
    def fill_windows(self, all_windows:dict):
        '''
        Fill the windows
        '''
        self._windows.clear()
        java_window = {}
        for h, v in all_windows.items():
            if self._is_java_window(h):
                java_window.update({h:v})
        for h,v in java_window.items():
            accessible_context, vmid = self._get_accessible_context_from_hwnd(h)
            if not accessible_context:
                continue
            root = JABElement(self.bridge, h, vmid, accessible_context)
            if root.is_showing():
                self.root_element = root
                self._hwnd = h
            self._windows.update({h: root} )

    def pre_init_jab(self) -> None:
        '''
        Prepare for initilization
        '''
        self.logger.info("pre init jab")
        self.initialized = False
        self.bridge = self.serv.load_library(self._bridge_dll)
        JABFixedFunc(self.bridge)._fix_bridge_functions()
        self.bridge.Windows_run()
        self._run_actor_sched()
        self.logger.info("pre init jab done")

    def init_jab(self, hwnd=None, waiting_time=10) -> None:
        '''
        Call it once Jab is created
        '''
        self.logger.info("init jab")

        self.refresh_windows(exit_if_modal=True)

        while not (self.hwnd and self.root_element and self.vmid  and self.accessible_context and self.windows):
            if hwnd is not None:
                if hwnd != self.hwnd or not self.hwnd:
                    self.hwnd = self.get_app_window_by_pid(self.pid, "SunAwtFrame")

            # wait java window by title and get hwnd if not specific hwnd and vmid
            try:
                if not self.title and len(self.windows) > 0:
                    for w in self.windows.values():
                        if w and w.name and w.children_count > 0:
                            self.title = w.name
                if not (self.hwnd) and self.title:    
                    self.hwnd = self.wait_java_window_by_title(
                        title=self.title, timeout=self._timeout
                    )
            except TimeoutError:
                pass
            self.expect_windows_change(None, waiting_time)
            self.refresh_windows(exit_if_modal=False)
            # get vmid and accessible_context by hwnd
            if self.hwnd and (not self.accessible_context or not self.vmid):
                self.accessible_context, self.vmid = self._get_accessible_context_from_hwnd(
                    self.hwnd
                )
            # get hwnd by vmid and accessible_context
            elif self.vmid and self.accessible_context and not self.hwnd:
                # must have vmid and accessible_context
                top_level_object = self.bridge.getTopLevelObject(
                    self.vmid, self.accessible_context
                )
                self.hwnd = self.bridge.getHWNDFromAccessibleContext(
                    self.vmid, top_level_object
                )
            elif self.pid and (not self.hwnd or not self.root_element):
                self.get_window_by_pid(self._pid)
            elif( not self.hwnd or not self.vmid or not self.accessible_context):
                raise RuntimeError(
                    "At least hwnd or vmid and accessible_context is required"
                )

            if self.pid is None and self.hwnd:
                self.pid = self.get_pid_from_hwnd()

            if self.root_element is None or not fnmatch.fnmatch(self.root_element.name, win32gui.GetWindowText(self.hwnd)):
                self.root_element = JABElement(
                    bridge=self.bridge,
                    hwnd=self.hwnd,
                    vmid=self.vmid,
                    accessible_context=self.accessible_context
                )

        self.initialized = True
        self.logger.info("init jab success")

    # Gateway functions
    def _is_java_window(self, hwnd: HWND) -> bool:
        """Return the specific window is or not a Java Window

        Args:
            hwnd (HWND): The hwnd of window.

        Returns:
            bool: True if is a Java Window. False is not a Java Window.
        """
        return bool(self.bridge.isJavaWindow(hwnd))
    
    def has_matching_window(self):
        '''
        Check if the window where root element resides is the expected by given title
        '''
        return self.root_element and fnmatch.fnmatch(self.root_element.name, self.title)

    def get_modal_window(self):
        '''
        Get a modal window if any
        '''
        for _, w  in self.windows.items():
            if States.MODAL in w.states:
                return w
        return None
    
    def handle_popup_window(self, title_button: dict):
        '''
        Handle the popup windows.
        Note that this function should be called prior to init_jab if the popup windows is blocking
        the main window to start up.
        '''
        ret = False
        while (self.get_modal_window()):
            ret  = ret or self.click_window_button(title_button)
            self.expect_windows_change(None, 5)
            self.refresh_windows(exit_if_modal=True)
        return ret
    
    def click_window_button(self, title_button: dict) -> bool:
        '''
        Click the button of the window if it appears
        '''
        ret = False
        for _, w  in self.windows.items():
            if w.name in title_button:
                button_name = title_button[w.name]
                if not isinstance(button_name, list): 
                    button_name=[button_name]
                for name in button_name:
                    button = w.find_element_by_name(name)
                    if button:
                        button.click()
                        ret =  True
        return ret

    def expect_windows_change(self, windows=None, timeout=10):
        '''
        Wait for expected windows change within a given timeout.
        Return False if no new change, True otherwise. 
        '''
        _windows = windows or self.windows
        new_windows = _windows
        start_time = time()
        self.logger.debug("Waiting for main window to appear")
        while(set(new_windows.keys()) == set(_windows.keys())):
            sleep(1)
            new_windows = self.enum_windows(exit_if_modal=False)
            if time() - start_time > timeout:
                return False
        return True

    def _get_accessible_context_from_hwnd(self, hwnd: HWND) -> Tuple[JOBJECT64, int]:
        """Gets the AccessibleContext and vmID values for the given window.

        Args:
            hwnd (HWND): hwnd (HWND): The hwnd of window.

        Returns:
            Tuple: tuple of AccessibleContext and vmID
        """
        if not hwnd or not self._is_java_window(hwnd):
            return None, 0
        
        vmid = c_long()
        accessible_context = JOBJECT64()
        self.bridge.getAccessibleContextFromHWND(
            hwnd, byref(vmid), byref(accessible_context)
        )
        return accessible_context, vmid.value

    def get_pid_from_hwnd(self, hwnd = None):
        hwnd = hwnd or self.hwnd
        _, pid = win32process.GetWindowThreadProcessId(hwnd)
        return pid

    def get_version_info(self) -> Dict[str, str]:
        """Gets the version information of the instance of Java Access Bridge instance your application is using.

        Returns:
            Dict[str]: Dict of AccessBridgeVersionInfo, contains:
                VMVersion
                bridgeJavaClassVersion
                bridgeJavaDLLVersion
                bridgeWinDLLVersion
        """
        info = AccessBridgeVersionInfo()
        self.bridge.getVersionInfo(self.vmid, byref(info))
        return {
            "VMVersion": info.VMVersion,
            "bridgeJavaClassVersion": info.bridgeJavaClassVersion,
            "bridgeJavaDLLVersion": info.bridgeJavaDLLVersion,
            "bridgeWinDLLVersion": info.bridgeWinDLLVersion,
        }

    def get_java_window_hwnd(self, title: str) -> Optional[HWND]:
        """Get Java Window hwnd by title.

        Args:
            title (str): Java window title

        Returns:
            Optional[HWND]: HWND if found Java Window, otherwise return None
        """
        for hwnd in self.win32utils.get_hwnds_by_title(title=title):
            if self._is_java_window(hwnd):
                return hwnd
    
    def get_app_window_by_pid(self, pid, class_name):
        """Get Java Window hwnd by pid.

        Args:
            pid (int): Java window's proces id

        Returns:
            Optional[HWND]: HWND if found Java Window, otherwise return None
        """
        windows = {}
        hwnds = []
        win32gui.EnumWindows(lambda hwnd, param: param.append(hwnd), hwnds)
        for hwnd in hwnds:
            _, found_pid = win32process.GetWindowThreadProcessId(hwnd)
            if found_pid == pid and win32gui.IsWindow(hwnd):
                window_title = win32gui.GetWindowText(hwnd) 
                window_class = win32gui.GetClassName(hwnd)
                if (class_name.lower() in window_class.lower()):
                    return  hwnd, window_title
        return None, ""
        
    def wait_java_window_by_title(self, title: str, timeout: int = TIMEOUT) -> HWND:
        """Wait until a Java Window exists in specific seconds.

        Args:
            title (str): The title of specific Java Window need to wait.
            timeout (int, optional): The timeout seconds. Defaults to TIMEOUT.

        Raises:
            TimeoutError: Timeout error occurs when wait time over the specific timeout

        Returns:
            HWND of Java window found in specific seconds.
        """
        start = time()
        while True:
            if hwnd := self.get_java_window_hwnd(title=title):
                return hwnd
            log_out = f"no java window found by title '{title}'"
            if self.latest_log != log_out:
                self.logger.debug(log_out)
                self.latest_log = log_out
            current = time()
            elapsed = round(current - start)
            if elapsed >= timeout:
                raise TimeoutError(
                    f"no java window found by title '{title}' in '{timeout}'seconds"
                )
            self._run_actor_sched()

    # jab driver functions: similar with webdriver
    def find_element_by_name(self, value: str, visible: bool = False) -> JABElement:
        """
        Find an JABElement given a name locator.
        """
        if value == self.root_element.name:
            return self.root_element
        else:
            return self.root_element.find_element_by_name(value=value, visible=visible)

    def find_element_by_description(self, value: str, visible: bool = False) -> JABElement:
        """
        Find an JABElement given a description locator.
        """
        if value == self.root_element.description:
            return self.root_element
        else:
            return self.root_element.find_element_by_description(value=value, visible=visible)

    def find_element_by_role(self, value: str, visible: bool = False) -> JABElement:
        """
        Find an JABElement given a role locator.
        """
        if value == self.root_element.role:
            return self.root_element
        else:
            return self.root_element.find_element_by_role(value=value, visible=visible)

