    def find_element(
            self, by: str = By.NAME, value: Any = None, visible: bool = False
    ) -> JABElement:
        """
        Find an JABElement given a By strategy and locator.
        """
        dict_find = {
            By.NAME: self.find_element_by_name,
            By.DESCRIPTION: self.find_element_by_description,
            By.ROLE: self.find_element_by_role,
            By.STATES: self.find_element_by_states,
            By.OBJECT_DEPTH: self.find_element_by_object_depth,
            By.CHILDREN_COUNT: self.find_element_by_children_count,
            By.INDEX_IN_PARENT: self.find_element_by_index_in_parent,
            By.XPATH: self.find_element_by_xpath,
            By.FULL_XPath: self.find_element_by_full_xpath,
            By.UID: self.find_element_by_uid
        }
        if by not in dict_find.keys():
            raise JABException(f"incorrect by strategy '{by}'")
        return dict_find[by](value=value, visible=visible)

    def _get_first_node_and_the_rest(self, s:str):
        '''
        Separate the first node and the rest.
        '''
        import re
        match = re.search(r'[^/]/', s)
        if match:
            index = match.start() + 1
            return s[:index], s[index:]
        else:
            return s, ""

    def find_window(self, first_node):
        '''
        Find the window by info of first node
        '''
        if hasattr(self, "windows"):
            for _, w in self.windows.items():
                if (w.name in first_node) and (w.role in first_node):
                    return w
        return None

    def find_element_by_full_xpath(self, value: str, visible: bool = False) -> JABElement:
        """
        Find an JABElement by given a full xpath, and the first node is a window or frame or dialog.
        """
        first_node, rest = self._get_first_node_and_the_rest(value)
        window = self.find_window(first_node)
        if window is not None:
            if rest == "":
                return window
            return window.find_element_by_xpath(rest, visible)

        return self.root_element.find_element_by_xpath(value=value, visible=visible)

